import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import type * as React from "react";

/**
 * The Sistine material system — the single source of the material → markup mapping.
 *
 * FIVE materials (glass, frosted, crystal, chakra, opaque), each a `[data-material]` token set in
 * app/theme/materials.css, composed with orthogonal AXES (border + its colour, veil, size, gradient, glow, sheen)
 * over the one structural `glass` utility. Components call `glassMaterial()` instead of hardcoding
 * recipe class strings (check-theme bans the legacy `glass-bg`/`glass-surface`/… classes).
 *
 * Semantics:
 * - `material` UNDEFINED = adaptive: no attribute is rendered; the surface follows the page's
 *   [data-glass] style (the default everywhere).
 * - An explicit material PINS the element under any page style, and — because the token set is
 *   inherited custom properties — also acts as a scoped default for adaptive glass descendants
 *   (a dialog set to frosted re-skins the controls inside it; pin a child back with its own material).
 * - `"none"` = not a glass surface: the helper returns nothing and the component supplies its plain
 *   (shadcn) classes.
 */
export type Material = "glass" | "frosted" | "crystal" | "chakra" | "opaque" | "none";

export interface MaterialProps {
  /** undefined = adaptive (follows the page style); "none" = the component's plain fallback. */
  material?: Material;
  /** Material border. Three weights: `true`/"hairline" = the material's edge (1px; 0.5px under
   *  frosted), "rim" = 2px, "frame" = 4px. */
  border?: boolean | "hairline" | "rim" | "frame";
  /** The border's COLOUR. "glass" (the default) = the material's own edge, a near-white rim at the
   *  material's alpha, which reads as glass but disappears on light themes at any weight. "ink" = the
   *  page's text colour (--foreground, at --glass-border-ink-a), a visible line wherever text is legible.
   *  Pairs with `border`; under the opaque page style it also colours the uniform panel edge. */
  borderColor?: "glass" | "ink";
  /** Element-composed legibility floor for read-through overlays (menus, tooltips, toasts). */
  veil?: boolean;
  /** Blur/elevation tier — INTERNAL: set by a component's ROLE (glass-sm/-lg), not a public prop
   *  ("size" universally means a component's dimensions; the material tier must never shadow that). */
  size?: "sm" | "lg" | "xl";
  /** Readability blur FLOOR (>= --glass-diffuse, default 12px) for text-dense translucent surfaces;
   *  inert under opaque. "stained" = the dyed mode: same floor, plus true stained-glass optics — the
   *  backdrop renders as TONAL SHADES of the theme hue (grayscale luminance collapse — the tint supplies the color). */
  diffuse?: boolean | "stained";
  /** Brand-gradient accent layered over the material. */
  gradient?: boolean;
  /** Resting glow, or the intensified "lg" halo. */
  glow?: boolean | "lg";
  /** Opt-in hover shimmer (pseudo-element based — avoid on sticky/fixed surfaces). */
  sheen?: boolean;
}

/** The PUBLIC per-instance axis props a component spreads onto its type. Excludes `size` (the material
 *  blur tier is a role-internal detail — a component's own `size` prop owns that name). */
export type MaterialAxisProps = Omit<MaterialProps, "size">;

/** The `rest` side of splitAxisProps. Distributes over union props (DayPicker's mode union, Radix
 *  ToggleGroup's single/multiple) so a discriminated union survives the split instead of collapsing
 *  under a bare Omit. */
export type SplitAxisRest<P> = P extends unknown ? Omit<P, keyof MaterialAxisProps> : never;

/** Split the material axis props off a component's props in ONE place — components never enumerate
 *  axis keys, so a NEW axis is zero-touch: extend MaterialProps + this destructure, done. `size` is
 *  role-internal (not in MaterialAxisProps) and stays in `rest` for the component's own cva. */
export function splitAxisProps<P extends MaterialAxisProps>(
  props: P,
): [
  MaterialAxisProps,
  SplitAxisRest<P>,
] {
  const { material, border, borderColor, veil, diffuse, gradient, glow, sheen, ...rest } = props;
  return [
    {
      material,
      border,
      borderColor,
      veil,
      diffuse,
      gradient,
      glow,
      sheen,
    },
    /* The conditional (distributive) rest type can't be proven for an unresolved P — safe by
     * construction: rest is exactly P minus the axis keys. */
    rest as SplitAxisRest<P>,
  ];
}

export interface MaterialAttrs {
  /** Spread-ready: undefined for adaptive and "none". */
  "data-material"?: Exclude<Material, "none">;
  /** "" when material === "none" (caller supplies its plain classes). */
  className: string;
}

export function glassMaterial(props: MaterialProps = {}): MaterialAttrs {
  const { material, border, borderColor, veil, size, diffuse, gradient, glow, sheen } = props;
  if (material === "none") {
    return {
      className: "",
    };
  }
  return {
    "data-material": material,
    className: [
      "glass",
      border && "glass-border",
      border === "rim" && "glass-border-rim",
      border === "frame" && "glass-border-frame",
      borderColor === "ink" && "glass-border-ink",
      veil && "glass-veil",
      size === "sm" && "glass-sm",
      size === "lg" && "glass-lg",
      size === "xl" && "glass-xl",
      diffuse && "glass-diffuse",
      diffuse === "stained" && "glass-stained",
      gradient && "glass-gradient",
      glow === "lg" ? "glass-glow-lg" : glow ? "glass-glow" : false,
      sheen && "glass-sheen",
    ]
      .filter(Boolean)
      .join(" "),
  };
}

/**
 * The component-facing resolver: merge a component's ROLE (its default axes for a given semantic
 * variant) with explicit per-instance material/axis props, and return the surface markup — or null
 * when the element is NOT a glass surface (role === null, or material === "none").
 *
 * Explicit props override the role per-axis; unspecified axes fall back to the role.
 */
export function materialSurface(role: MaterialProps | null, props: MaterialProps): MaterialAttrs | null {
  if (props.material === "none" || role === null) {
    return null;
  }
  return glassMaterial({
    material: props.material,
    border: props.border ?? role.border,
    borderColor: props.borderColor ?? role.borderColor,
    veil: props.veil ?? role.veil,
    size: props.size ?? role.size,
    diffuse: props.diffuse ?? role.diffuse,
    gradient: props.gradient ?? role.gradient,
    glow: props.glow ?? role.glow,
    sheen: props.sheen ?? role.sheen,
  });
}

/**
 * Typed per-element knobs → CSS custom properties ONLY (the cascade-native successor to the old
 * `glass={{…}}` inline-style prop). Everything routes through the token system, so nothing here can
 * fight a material, a page style, or the theme.
 *
 * The tint* keys recolor engine-composed tokens, which re-resolve at grouped declarations — pair
 * them with a `data-glass-tint` attribute on the same element so the engine re-composes there.
 */
export interface GlassVars {
  /** → --glass-tint-h (surface hue) */
  tintH?: number;
  /** → --glass-tint-c (surface chroma — the colorfulness master) */
  tintC?: number;
  /** → --glass-tint-a (tint film alpha) */
  tintA?: number;
  /** → --glass-opacity (0..1 solidify dial; element-composed in `glass`) */
  opacity?: number;
  /** → --srf-blur (number → px; glass material only) */
  blur?: number | string;
  /** → --glass-solid-a (veil floor alpha; element-composed in `glass-veil`) */
  solidA?: number;
}

export function glassVars(v: GlassVars = {}): React.CSSProperties {
  const s: Record<string, string> = {};
  if (v.tintH !== undefined) {
    s["--glass-tint-h"] = String(v.tintH);
  }
  if (v.tintC !== undefined) {
    s["--glass-tint-c"] = String(v.tintC);
  }
  if (v.tintA !== undefined) {
    s["--glass-tint-a"] = String(v.tintA);
  }
  if (v.opacity !== undefined) {
    s["--glass-opacity"] = String(v.opacity);
  }
  if (v.blur !== undefined) {
    s["--srf-blur"] = typeof v.blur === "number" ? `${v.blur}px` : v.blur;
  }
  if (v.solidA !== undefined) {
    s["--glass-solid-a"] = String(v.solidA);
  }
  return s as React.CSSProperties;
}

import { cva } from "class-variance-authority";

/**
 * Shared hover effect variants for all Sistine components
 *
 * Effects:
 * - none: No hover effect
 * - glow: Themed glow shadow (--glass-glow, follows the tint hue) that intensifies on hover
 * - shimmer: Moving shimmer effect across the component
 * - ripple: Ripple effect that scales outward on hover
 * - lift: Subtle lift effect with shadow increase
 * - scale: Scale up slightly on hover
 */
export const hoverEffects = cva("transition duration-300", {
  variants: {
    hover: {
      none: "",
      glow: "glass-glow hover:glass-glow-lg",
      shimmer:
        "relative overflow-hidden before:absolute before:inset-0 before:-translate-x-full before:bg-gradient-to-r before:from-transparent before:via-white/20 before:to-transparent hover:before:translate-x-full before:transition-transform before:duration-1000",
      ripple:
        "relative overflow-hidden after:absolute after:inset-0 after:scale-0 after:rounded-full after:bg-white/30 after:transition-transform after:duration-500 hover:after:scale-150",
      lift: "hover:-translate-y-1 hover:shadow-lg",
      scale: "hover:scale-105",
    },
  },
  defaultVariants: {
    hover: "none",
  },
});

export type HoverEffect = "none" | "glow" | "shimmer" | "ripple" | "lift" | "scale";

"use client";

import { X } from "@phosphor-icons/react";
import { cva, type VariantProps } from "class-variance-authority";
import { Dialog as DialogPrimitive } from "radix-ui";
import * as React from "react";
import { type MaterialAxisProps, type MaterialProps, materialSurface, splitAxisProps } from "@/lib/material";
import { cn } from "@/lib/utils";
import { Button } from "./button";

/* Variant classes carry BEHAVIOR only; the surface comes from materialSurface. */
const dialogContentVariants = cva("", {
  variants: {
    variant: {
      default: "bg-background border",
      glass: "text-foreground",
    },
  },
  defaultVariants: {
    variant: "glass",
  },
});

/* Role: bordered adaptive glass at the elevated blur tier. */
const ROLE: MaterialProps = {
  border: true,
  size: "lg",
};

const Dialog = DialogPrimitive.Root;

/* Trigger and Close stamp their data-slot (consumers style and test against it), as the content's own close
   button already did; Root and Portal render no element of their own, so they stay plain aliases. */
const DialogTrigger = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Trigger>
>((props, ref) => <DialogPrimitive.Trigger ref={ref} data-slot="dialog-trigger" {...props} />);
DialogTrigger.displayName = DialogPrimitive.Trigger.displayName;

const DialogPortal = DialogPrimitive.Portal;

const DialogClose = React.forwardRef<React.ElementRef<typeof DialogPrimitive.Close>, React.ComponentPropsWithoutRef<typeof DialogPrimitive.Close>>(
  (props, ref) => <DialogPrimitive.Close ref={ref} data-slot="dialog-close" {...props} />,
);
DialogClose.displayName = DialogPrimitive.Close.displayName;

const DialogOverlay = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Overlay>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Overlay
    ref={ref}
    data-slot="dialog-overlay"
    className={cn(
      "fixed inset-0 z-50 bg-transparent backdrop-blur-md data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0",
      className,
    )}
    {...props}
  />
));
DialogOverlay.displayName = DialogPrimitive.Overlay.displayName;

const DialogContent = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Content> &
    VariantProps<typeof dialogContentVariants> &
    MaterialAxisProps & {
      /** Elevated backdrop blur (folded from the glass wrapper). */
      animated?: boolean;
      /** Styles the layout wrapper around `children` (`data-slot="dialog-layout"`). `className` targets
       *  the OUTER surface, so without this a consumer has no way to change the body's layout — swap the
       *  grid for flex, drop the gap, or take the scrolling over entirely.
       *  Its `-m-6 p-6` is a matched pair that cancels the dialog's padding so the scroll container
       *  stops clipping child shadows; override one and you must override the other. */
      bodyClassName?: string;
      showCloseButton?: boolean;
    }
>(({ className, variant = "glass", children, animated = true, bodyClassName, showCloseButton = true, ...props }, ref) => {
  const [axes, rest] = splitAxisProps(props);
  const m = materialSurface(variant === "default" ? null : ROLE, axes);

  return (
    <DialogPortal data-slot="dialog-portal">
      <DialogOverlay />
      <DialogPrimitive.Content
        ref={ref}
        data-slot="dialog-content"
        data-material={m?.["data-material"]}
        className={cn(
          m?.className,
          // Centered WITHOUT a transform. The usual `left-1/2 top-1/2 -translate-1/2` lands any
          // odd-pixel-sized dialog on a half pixel, and on a composited glass surface every glyph then
          // rasterizes off the pixel grid — visibly blurry text. `inset-0 m-auto h-fit` centers through
          // layout instead, which snaps to whole pixels. (This is why the inset-positioned sheet was
          // always crisp and dialogs were not.) The slide-* utilities are gone with it: they existed
          // only to offset that base translate, and here they would drag the dialog off-centre. Fade +
          // zoom both END AT IDENTITY, so nothing is left on a fractional transform once open.
          // NOTE the underscores in the max-h arbitrary value: Tailwind turns them into spaces, and
          // `calc(100dvh-2rem)` without them is invalid CSS (calc needs whitespace around - and +), so the
          // whole declaration is silently dropped and the cap does nothing.
          // max-h + an inner scroll area: without a cap, content taller than the viewport simply ran off
          // the bottom with no way to reach it. The DIALOG keeps overflow-hidden (it clips the rounded
          // corners and keeps the absolutely-positioned close button pinned); the scrolling happens in
          // the wrapper around {children} below, so the close button never scrolls out of reach.
          // grid-rows-[minmax(0,1fr)] is the other half of it: an IMPLICIT auto row sizes to its content
          // and happily overflows a max-height, so the wrapper never became scrollable and the dialog
          // just clipped. minmax(0,1fr) lets the row shrink, which is what hands the overflow to the
          // wrapper's overflow-y-auto.
          // `min(100% − 2rem, 32rem)` keeps a 1rem gutter each side on narrow screens (at `w-full
          // max-w-lg` it ran edge to edge below 512px), and outline-hidden stops the browser outline
          // ringing the whole panel when Radix focuses the content itself (nothing tabbable inside).
          "@container/dialog-content fixed inset-0 z-50 m-auto grid h-fit max-h-[calc(100dvh_-_2rem)] grid-rows-[minmax(0,1fr)] w-full max-w-[min(calc(100%-2rem),32rem)] gap-4 overflow-hidden rounded-lg p-6 shadow-lg outline-hidden duration-200 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95",
          dialogContentVariants({
            variant,
          }),
          className,
        )}
        {...rest}
      >
        {/* The layout wrapper has two modes.
            WITHOUT a DialogBody child it is the scroll box, as it always was: header, content and footer
            scroll together.
            WITH one (`has-[>[data-slot=dialog-body]]:`) it becomes a non-clipping flex column and only
            the body scrolls: the header and footer are chrome, not content, and inside a scroll box a
            glass button's glow was sliced at whichever edge it touched (overflow-y:auto clips on all
            four sides, see below), and the footer scrolled away with the text.
            min-w-0 + [&>*]:min-w-0: grid and flex items default to min-width:auto, so one unbreakable
            child (a long path with `truncate`) set the track WIDER than the dialog and every line laid
            out to that phantom width, clipped at the border. Letting the items shrink fixes wrap/truncate.
            min-h-0 is load-bearing: a grid item defaults to min-height:auto, which refuses to shrink
            below its content, so without it this never scrolls and the dialog just clips again.
            -m-6 p-6 cancels the dialog's own p-6 so this box's edges land ON the dialog's padding box
            instead of its content box. That matters because `overflow-y: auto` is not one-axis: when
            either axis is non-visible the other computes visible -> auto, so this is a scroll
            container HORIZONTALLY too, and a scroll container clips at its padding box. Sitting at the
            content box it sheared every child's box-shadow flat 24px inside the dialog edge — a hard
            vertical cut down the side of the last footer button and a hard horizontal one under the
            footer row. Cancelling the padding moves that clip out to where the dialog's own
            overflow-hidden already clips, which does the same job and follows the rounded corners.
            The two utilities are a pair: overriding padding alone via bodyClassName re-offsets the
            body by the leftover negative margin. */}
        <div
          data-slot="dialog-layout"
          className={cn(
            "-m-6 grid min-h-0 min-w-0 gap-4 overflow-y-auto p-6 [&>*]:min-w-0",
            "has-[>[data-slot=dialog-body]]:flex has-[>[data-slot=dialog-body]]:flex-col has-[>[data-slot=dialog-body]]:overflow-visible",
            bodyClassName,
          )}
        >
          {children}
        </div>
        {showCloseButton && (
          <DialogPrimitive.Close
            data-slot="dialog-close"
            className="absolute right-4 top-4 rounded-sm opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:outline-hidden focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:pointer-events-none data-[state=open]:bg-accent data-[state=open]:text-muted-foreground"
          >
            <X className="h-4 w-4" />
            <span className="sr-only">Close</span>
          </DialogPrimitive.Close>
        )}
      </DialogPrimitive.Content>
    </DialogPortal>
  );
});
DialogContent.displayName = DialogPrimitive.Content.displayName;

const DialogHeader = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    data-slot="dialog-header"
    className={cn("flex shrink-0 flex-col space-y-1.5 text-center @sm/dialog-content:text-left", className)}
    {...props}
  />
);
DialogHeader.displayName = "DialogHeader";

/**
 * The scrolling region of a dialog. Optional: put it between DialogHeader and DialogFooter and only it
 * scrolls, with the header and footer fixed around it; leave it out and the whole dialog content scrolls
 * as one, as before.
 * `-mx-6 px-6` runs the scroll box out to the dialog's edges (a scroll container clips at its padding
 * box, so sitting at the content box it sheared child shadows 24px inside the edge), and `-my-2 py-2`
 * gives a glow 8px of room above and below without moving the content.
 */
const DialogBody = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    data-slot="dialog-body"
    className={cn("-mx-6 -my-2 grid min-h-0 flex-1 gap-4 overflow-y-auto px-6 py-2 [&>*]:min-w-0", className)}
    {...props}
  />
);
DialogBody.displayName = "DialogBody";

const DialogFooter = ({
  className,
  showCloseButton = false,
  children,
  ...props
}: React.HTMLAttributes<HTMLDivElement> & {
  showCloseButton?: boolean;
}) => (
  <div
    data-slot="dialog-footer"
    className={cn("flex shrink-0 flex-col-reverse gap-2 @sm/dialog-content:flex-row @sm/dialog-content:justify-end", className)}
    {...props}
  >
    {children}
    {showCloseButton && (
      <DialogPrimitive.Close asChild>
        <Button variant="outline">Close</Button>
      </DialogPrimitive.Close>
    )}
  </div>
);
DialogFooter.displayName = "DialogFooter";

const DialogTitle = React.forwardRef<React.ElementRef<typeof DialogPrimitive.Title>, React.ComponentPropsWithoutRef<typeof DialogPrimitive.Title>>(
  ({ className, ...props }, ref) => (
    <DialogPrimitive.Title
      ref={ref}
      data-slot="dialog-title"
      className={cn("text-lg font-semibold leading-none tracking-tight", className)}
      {...props}
    />
  ),
);
DialogTitle.displayName = DialogPrimitive.Title.displayName;

const DialogDescription = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Description>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Description>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Description ref={ref} data-slot="dialog-description" className={cn("text-sm text-muted-foreground", className)} {...props} />
));
DialogDescription.displayName = DialogPrimitive.Description.displayName;

export {
  Dialog,
  DialogBody,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogOverlay,
  DialogPortal,
  DialogTitle,
  DialogTrigger,
};
